const items = $input.all();
const first = items[0] ? items[0].json : {};
return [{
  json: {
    status: "success",
    message: "Brandbook gerado e salvo via SSH no VPS com sucesso pelo BRAND OS!",
    project_id: first.project_id,
    nome_empresa: first.nome_empresa,
    total_arquivos: items.length,
    path_servidor: `/Brandbook/${first.project_id}/`
  }
}];

const inputData = $input.first().json;
const data = inputData.data;
const strategist = inputData.strategistOutput || {};
const branding = inputData.brandingPersonaOutput || {};
const copyVerbal = inputData.copyVerbalOutput || {};
const visual = inputData.visualOutput || {};

const files = [];

const addFile = (filename, content, title) => {
  const body = content || `# ${title}\n\nInformações em processamento para a marca ${data.nome_empresa}.`;
  files.push({ filename, content: body });
};

addFile("brand-context.md", strategist.brand_context || `# Brand Context - ${data.nome_empresa}\n\n${data.descricao_empresa}`, "Brand Context");
addFile("01-empresa.md", strategist.empresa_md, "01 - A Empresa");
addFile("02-proposito.md", strategist.proposito_md, "02 - Propósito da Marca");
addFile("03-missao-visao-valores.md", strategist.missao_visao_valores_md, "03 - Missão, Visão e Valores");
addFile("04-posicionamento.md", strategist.posicionamento_md, "04 - Posicionamento no Mercado");
addFile("05-publico-alvo.md", branding.publico_alvo_md, "05 - Público-Alvo");
addFile("06-persona.md", branding.persona_md, "06 - Perfil do Cliente Ideal (Persona)");
addFile("07-proposta-de-valor.md", branding.proposta_de_valor_md, "07 - Proposta Única de Valor");
addFile("08-personalidade-da-marca.md", branding.personalidade_md, "08 - Personalidade da Marca");
addFile("09-tom-de-voz.md", copyVerbal.tom_de_voz_md, "09 - Tom de Voz e Comunicação");
addFile("10-arquetipos.md", branding.arquetipos_md, "10 - Arquétipos de Marca");
addFile("11-identidade-verbal.md", copyVerbal.identidade_verbal_md, "11 - Diretrizes de Identidade Verbal");
addFile("12-identidade-visual.md", visual.identidade_visual_md, "12 - Diretrizes de Identidade Visual");
addFile("13-paleta-de-cores.md", visual.paleta_de_cores_md, "13 - Paleta de Cores");
addFile("14-tipografia.md", visual.tipografia_md, "14 - Tipografia Institucional");
addFile("15-diretrizes-de-logo.md", visual.diretrizes_de_logo_md, "15 - Diretrizes de Uso da Logo");
addFile("16-mensagens-chave.md", copyVerbal.mensagens_chave_md, "16 - Mensagens-Chave");
addFile("17-storytelling.md", copyVerbal.storytelling_md, "17 - Narrativa e Storytelling");
addFile("18-manifesto.md", copyVerbal.manifesto_md, "18 - Manifesto da Marca");

const readmeContent = `# Brandbook Oficial — ${data.nome_empresa}\n\nEste repositório contém toda a documentação estratégica.\n\n## Arquivo Principal\n- brand-context.md`;
addFile("README.md", readmeContent, "README");

return files.map(file => ({
  json: {
    project_id: data.project_id,
    nome_empresa: data.nome_empresa,
    filename: file.filename,
    content: file.content,
    file_path: `/Brandbook/${data.project_id}/${file.filename}`
  }
}));

const response = $input.first().json;

let parsed = {};

try {

  let content = response.output ?? response.text ?? response.content;

  if (!content && response.choices?.[0]?.message?.content) {
    content = response.choices[0].message.content;
  }

  if (typeof content === "string") {

    content = content
      .replace(/^```json\s*/i, "")
      .replace(/^```\s*/i, "")
      .replace(/```\s*$/i, "")
      .trim();

    parsed = JSON.parse(content);

  } else if (typeof content === "object" && content !== null) {
    parsed = content;
  }

} catch (e) {

  parsed = {
    parse_error: e.message,
    raw_response: response
  };

}

const prevNode = $("Parse Copywriter").first().json;

return [{
  json: {
    data: prevNode.data,
    apiKey: prevNode.apiKey,
    strategistOutput: prevNode.strategistOutput,
    brandingPersonaOutput: prevNode.brandingPersonaOutput,
    copyVerbalOutput: prevNode.copyVerbalOutput,
    visualOutput: parsed
  }
}];

