const raw = $input.first().json.body || $input.first().json;

const nomeEmpresa = raw.nome_empresa || raw.nome || "Empresa Sem Nome";

const rawSlug = nomeEmpresa
  .toLowerCase()
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .replace(/[^a-z0-9]+/g, "-")
  .replace(/(^-|-$)/g, "");

const projectSlug = `${rawSlug}-${Date.now()}`;

const data = {
  project_id: projectSlug,
  nome_empresa: nomeEmpresa,
  descricao_empresa: raw.descricao_empresa || "",
  segmento: raw.segmento || "Geral",
  produtos_servicos: raw.produtos_servicos || [],
  publico_atual: raw.publico_atual || "",
  publico_desejado: raw.publico_desejado || "",
  diferenciais: raw.diferenciais || [],
  historia_empresa: raw.historia_empresa || "",
  missao_atual: raw.missao_atual || "",
  visao_atual: raw.visao_atual || "",
  valores_atuais: raw.valores_atuais || [],
  concorrentes: raw.concorrentes || [],
  objetivos_empresa: raw.objetivos_empresa || [],
  problemas_resolvidos: raw.problemas_resolvidos || [],
  personalidade_desejada: raw.personalidade_desejada || [],
  cores_preferidas: raw.cores_preferidas || [],
  restricoes: raw.restricoes || [],
  site: raw.site || "",
  redes_sociais: raw.redes_sociais || []
};

return [{
  json: {
    data,
    apiKey: raw.openai_api_key || ""
  }
}];

